            'PUBDEV_MAX_POLLS': '2',
          },
        );
        expect(r.exitCode, 0, reason: r.output);
        expect(r.inFlight, isTrue, reason: r.output);
        expect(r.errored, isFalse, reason: 'no alarm when the re-arm heals');
