        .map((s) => s as YamlMap)
        .firstWhere(
          (s) =>
              s['uses']?.toString().startsWith('actions/checkout') ?? false,
        );
    expect(
      checkout['with']['token']?.toString(),
      equals(r'${{ steps.app-token.outputs.token || github.token }}'),
      reason:
