      expect(
        steps
            .map((s) => (s as YamlMap)['uses']?.toString() ?? '')
            .any((uses) => uses.startsWith(banned)),
        isFalse,
        reason:
            'gh-1522: the tag-only release job never installs an SDK — '
            'tag cutting is git+gh only (no flutter pub get / no python '
            'file bumps)',
      );
    }
  },
);
